INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'ac204165-cbb2-5ecf-9a52-032fa72c8498', '6df2a5bf-83f3-5223-8b07-c6ad66de87fd',
  '[L.O.3.1] Cho bảng băm sử dụng hàm băm $h(k) = k \mod 11$, phương pháp dò tìm bình phương để giải quyết đụng độ $hp(k, i) = (h(k) + i + 3i^2) \mod 11$. Nhận xét nào sau đây là đúng khi lần lượt thêm các giá trị 10, 22, 31, 4, 15, 28, 17, 88, 59 vào bảng? (GCCC: gom cụm chính cấp, primary clustering, GCTC: gom cụm thứ cấp, secondary clustering)

Lựa chọn:
- A) GCTC đã xảy ra ở các vị trí 4, 6, 10, 9
- B) GCTC đã xảy ra ở các vị trí 0, 3, 4, 8
- C) GCCC đã xảy ra ở các vị trí 0, 3, 4, 8
- D) GCCC đã xảy ra ở các vị trí 4, 6, 10, 9', 9
);

