INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c0d30f7f-fc58-5936-b8e9-2fb776bbfaf5', '6df2a5bf-83f3-5223-8b07-c6ad66de87fd',
  '**Câu 17.** (0.5 điểm) [L.O.2.1] Cho bảng băm (hash table) sử dụng hàm băm (hash function) $h(k) = (3k + 1) \mod 16$. Phương pháp giải quyết đụng độ là dò tìm tuyến tính (linear probing) với $hp(k, i) = (h(k) + i) \mod 16$.

