INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c558eb6a-efd6-5846-8a56-1c254d9684fd', '6df2a5bf-83f3-5223-8b07-c6ad66de87fd',
  '[L.O.2.1] Cho bảng băm (hash table) sử dụng hàm băm (hash function) $h(k) = (3k + 1) \mod 13$. Phương pháp giải quyết đụng độ là dò tìm tuyến tính (linear probing) với $hp(k, i) = (h(k) + i) \mod 13$.

Ghi lại bảng băm trên khi thêm lần lượt các giá trị 8, 12, 40, 13, 88, 45, 29, 20, 23, 77 vào bảng.', 30
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '9d15b34c-e1a0-5e8e-9ddf-d8e24ed06600', '6df2a5bf-83f3-5223-8b07-c6ad66de87fd',
  '**Câu 18.** (3 điểm) Trong một chương trình, người ta cần lưu trữ tọa độ trong không gian hình học Oxy của một tập hợp các điểm phân biệt. Người ta tạo ra một cấu trúc cây nhị phân tìm kiếm (BST) để lưu trữ các điểm trên theo khoảng cách Euclidean từ điểm đó đến gốc tọa độ O(0, 0) như sau:

```cpp
class Point {
public:
    double x, y;
    Point* left;
    Point* right;
};

class Space {
private:
    Point* root;
public:
    void add(double x, double y);
};
```

Sử dụng ngôn ngữ lập trình C/C++, sinh viên hãy:

(a) [L.O.2.2] Hiện thực phương thức `add` đã định nghĩa trong đoạn mã trên thêm một điểm có tọa độ (x, y) vào trong cấu trúc lưu trữ.

(b) [L.O.2.2] Hiện thực phương thức `vector<Point> inAnnulus(double r, double R)` trong lớp `Space` để trả về danh sách các điểm nằm trong hình vành khăn được tạo bởi hai hình tròn tâm O có bán kính $0 < r < R$.

(c) [L.O.3.3] Hiện thực phương thức `void printSymmetry(bool axis = true)` để in ra màn hình tất cả các cặp điểm đối xứng nhau qua trục Ox nếu `axis` mang giá trị `true`, ngược lại thì đối xứng qua trục Oy. Không quan tâm đến thứ tự giữa các cặp và giữa các điểm trong cặp. Ví dụ về định dạng khi in:

(0, 1) (0, -1)
(1, 1) (1, -1)

Sinh viên được phép viết thêm hàm phụ trợ để hoàn thành các câu hỏi trên. Bỏ qua sai số khi tính toán với số thực double trên C++.

**Lưu ý về định nghĩa:** Cây nhị phân tìm kiếm (BST) là cây nhị phân với đặc điểm sau:

* Tất cả các khóa trên cây con bên trái đều nhỏ hơn khóa tại gốc.
* Tất cả các khóa trên cây con bên phải đều lớn hơn hoặc bằng khóa tại gốc.
* Mỗi cây con là một cây nhị phân tìm kiếm.', 31
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'dd73fe3f-d9f3-5e4d-ad4d-05f3d09268c7', '6df2a5bf-83f3-5223-8b07-c6ad66de87fd',
  '**Câu 19. (1 điểm)**

(a) [L.O.2.2] Để sắp xếp dãy N phần tử ta có thể dùng heap sort. Các phương thức cơ bản của heap xem như được cung cấp trước như $reHeapUp$, $reHeapDown$. Hãy hiện thực giải thuật build heap với độ phức tạp $O(N)$.

(b) [L.O.1.2] Hãy đề xuất một giải thuật sắp xếp N phần tử bằng cách sử dụng cây AVL làm trung gian. Cho biết độ phức tạp của giải thuật vừa đề xuất.', 32
);

